            # Only modify .m4v segments and if __bgda__ parameter doesn't already exist
            if ".m4v" in segment.uri and "__bgda__" not in segment.uri:
                segment.uri = update_qsd(segment.uri, {"__bgda__": self.stream.bgda_param}, safe="=")

    return super().process_segments(playlist)

def stream_resource_content(
    request_id: RequestId,
) -> Generator[T_JSON_DICT, T_JSON_DICT, str]:
    """
    Enables streaming of the response for the given requestId.
    If enabled, the dataReceived event contains the data that was received during streaming.

    **EXPERIMENTAL**

    :param request_id: Identifier of the request to stream.
    :returns: Data that has been buffered until streaming is enabled. (Encoded as a base64 string when passed over JSON)
    """
    params: T_JSON_DICT = {}
    params["requestId"] = request_id.to_json()
    cmd_dict: T_JSON_DICT = {
        "method": "Network.streamResourceContent",
        "params": params,
    }
    json = yield cmd_dict
    return str(json["bufferedData"])

