    for stream in streams:
        if stream["type"] == "application/x-mpegURL":
            if quality != "auto":
                # Avoid duplicate HLS streams with bitrate selector in the URL query
                continue
            yield from HLSStream.parse_variant_playlist(self.session, stream["url"]).items()
